-- Follow-up to 20260819120000: that migration only added the GSO_1943
-- (label) checkSet group. Confirmed live: a reviewer manually overriding
-- ANY claim's verdict to Compliant/Non-Compliant (workflow doc §12 —
-- reviewers can modify "Claim results") produces a real promotable verdict
-- whose code wasn't in any checkSet, and promoteToOfficialChecklist refuses
-- to promote the WHOLE assessment on a single unknown code
-- (CODE_MISMATCH) — not just that one claim. Add a second checkSet group,
-- GSO_2528, covering all 102 claim codes, so manually-resolved claims don't
-- silently block promotion of everything else.
--
-- Appends to the existing checkSets array (jsonb ||) rather than replacing
-- it, so it composes cleanly with 20260819120000 regardless of apply order.

UPDATE "ServiceItem"
SET "checkSets" = "checkSets" || $v$[{"code":"GSO_2528","titleEn":"GSO 2528 — Cosmetic marketing claims","titleAr":"GSO 2528 — الادعاءات التسويقية لمستحضرات التجميل","items":[{"code":"CLAIM-GEN-1-1","titleEn":"Does the product contact only the external parts of the body?","titleAr":"هل يلامس المنتج الأجزاء الخارجية فقط للجسم؟"},{"code":"CLAIM-GEN-1-2","titleEn":"Is the function limited to the cosmetic purposes (cleaning, perfuming, changing appearance, protecting, keeping in good condition, correcting body odors)?","titleAr":"هل الوظيفة تقتصر على الأغراض التجميلية الخمسة؟"},{"code":"CLAIM-GEN-1-3","titleEn":"Is the claim free from claiming to treat pathological conditions or diseases?","titleAr":"هل يخلو الادعاء من علاج حالات مرضية؟"},{"code":"CLAIM-GEN-1-4","titleEn":"Is the claim free from implying a major change in physiological functions?","titleAr":"هل يخلو الادعاء من التغيير الكبير في الوظائف الفسيولوجية؟"},{"code":"CLAIM-GEN-1-5","titleEn":"Is the claim free from implying effects on metabolism?","titleAr":"هل يخلو الادعاء من التأثير في عملية التمثيل الغذائي؟"},{"code":"CLAIM-GEN-2-1","titleEn":"Does the claim comply with local laws, Islamic values, and societal customs?","titleAr":"هل يتوافق الادعاء مع القوانين المحلية والقيم الإسلامية وعادات المجتمع؟"},{"code":"CLAIM-GEN-2-2","titleEn":"Is the claim language clear, understandable, and acceptable to general consumers?","titleAr":"هل لغة الادعاء مفهومة ومقبولة لدى عموم المستهلكين؟"},{"code":"CLAIM-GEN-2-3","titleEn":"Does the claim avoid portraying mandatory minimum legal requirements as special unique features?","titleAr":"هل يخلو الادعاء من تصوير المتطلبات الدنيا كأنها ميزة خاصة؟"},{"code":"CLAIM-GEN-2-4","titleEn":"Is the claim free from any indication that the product is licensed or approved by a regulatory body?","titleAr":"هل يخلو الادعاء من أي إشارة إلى أن المنتج مرخص أو معتمد؟"},{"code":"CLAIM-GEN-3-1","titleEn":"Is the general presentation of claims free from false or misleading information?","titleAr":"هل العرض العام للادعاءات خالٍ من أي معلومات خاطئة؟"},{"code":"CLAIM-GEN-3-2","titleEn":"0","titleAr":"هل ادعاءات المنتج صحيحة كلياً وغير مضللة؟"},{"code":"CLAIM-GEN-3-3","titleEn":"0","titleAr":"في حال ادعاء وجود مادة معينة، هل هي موجودة فعلياً في المكونات؟"},{"code":"CLAIM-GEN-3-4","titleEn":"0","titleAr":"هل يخلو المنتج من استغلال خصائص مكوّن واحد لتعميمها على المنتج النهائي؟"},{"code":"CLAIM-GEN-3-5","titleEn":"0","titleAr":"هل الادعاءات متوافقة في المعنى بجميع اللغات المدوّنة على العبوة؟"},{"code":"CLAIM-GEN-4-1","titleEn":"0","titleAr":"هل الادعاء (صريحاً أو ضمنياً) مدعوم بأدلة كافية وقابلة للتحقق؟"},{"code":"CLAIM-GEN-4-2","titleEn":"0","titleAr":"هل هناك ربط مباشر بين الدراسات المرجعية وبين المستحضر النهائي؟"},{"code":"CLAIM-GEN-4-3","titleEn":"0","titleAr":"هل تم استخدام طرق إثبات علمية صحيحة وموثوقة وقابلة لإعادة التجربة؟"},{"code":"CLAIM-GEN-4-4","titleEn":"0","titleAr":"هل يتناسب مستوى الدليل مع نوع وقوة الادعاء؟"},{"code":"CLAIM-GEN-4-5","titleEn":"0","titleAr":"هل يستند قبول الادعاء على مجموع الأدلة وليس دراسة واحدة معزولة؟"},{"code":"CLAIM-GEN-5-1","titleEn":"0","titleAr":"هل يخلو عرض أداء المنتج من أي نوع من المبالغة؟"},{"code":"CLAIM-GEN-5-2","titleEn":"0","titleAr":"هل الصور (قبل وبعد) طبيعية ولم تخضع لتعديلات مضللة؟"},{"code":"CLAIM-GEN-5-3","titleEn":"0","titleAr":"هل يخلو المنتج من ادعاء «خالٍ من» لمواد لا يستدعي المنتج وجودها أصلاً؟"},{"code":"CLAIM-GEN-5-4","titleEn":"0","titleAr":"هل يتجنب المنتج ادعاء التفرد في خصائص يمتلكها المنافسون أيضاً؟"},{"code":"CLAIM-GEN-5-5","titleEn":"0","titleAr":"هل نتائج المنتج المدعاة مرتبطة بظروف استخدام محددة؟"},{"code":"CLAIM-GEN-6-1","titleEn":"0","titleAr":"هل ادعاءات المنتج موضوعية ولا تهدف للتقليل من شأن المنافسين؟"},{"code":"CLAIM-GEN-6-2","titleEn":"0","titleAr":"هل يخلو الادعاء من المقارنات غير العادلة التي توهم بأفضلية مطلقة؟"},{"code":"CLAIM-GEN-6-3","titleEn":"0","titleAr":"هل يتجنب الادعاء التقليل من شأن مكونات مسموح بها قانونياً؟"},{"code":"CLAIM-GEN-6-4","titleEn":"0","titleAr":"هل تعتمد المقارنات على معايير يحددها المستهلك كمنفعة أو رغبة؟"},{"code":"CLAIM-GEN-7-1","titleEn":"0","titleAr":"هل الادعاءات واضحة ومفهومة للمستخدم النهائي المستهدف؟"},{"code":"CLAIM-GEN-7-2","titleEn":"0","titleAr":"هل راعى المسوّقون المقدرة الاستيعابية للفئة المستهدفة؟"},{"code":"CLAIM-GEN-7-3","titleEn":"0","titleAr":"هل المعلومات المقدمة ذات علاقة مباشرة بوظيفة المستحضر؟"},{"code":"CLAIM-GEN-7-4","titleEn":"0","titleAr":"هل يتوافق المعنى في جميع اللغات والوسائل المستخدمة؟"},{"code":"CLAIM-الع-1","titleEn":"Makes skin younger","titleAr":"يجعل الجلد أكثر شباباً"},{"code":"CLAIM-الع-1-r83","titleEn":"Enhances sperm motility / improves conception","titleAr":"يعزز من حركة الحيوانات المنوية / يزيد من فرص حدوث الحمل"},{"code":"CLAIM-الع-1-r93","titleEn":"Any implication of effect below the gum line","titleAr":"أي تلميح على التأثير تحت اللثة"},{"code":"CLAIM-الع-10","titleEn":"Works on / from the inside","titleAr":"يعمل على / أو من داخل"},{"code":"CLAIM-الع-10-r92","titleEn":"Any reference to head lice","titleAr":"أي إشارة إلى القمل"},{"code":"CLAIM-الع-11","titleEn":"Any reference to action on dermis","titleAr":"الإشارة إلى إحداث أي تغيير على أدمة الجلد"},{"code":"CLAIM-الع-12","titleEn":"Any sign to stimulate skin synthesis of collagen, elastin, enzymes","titleAr":"أي إشارة إلى تحفيز / تنشيط / تحسين إنتاج الكولاجين أو الإيلاستين أو الإنزيمات"},{"code":"CLAIM-الع-13","titleEn":"Collagen / elastin / skin enzyme synthesis, replenishment, stimulation or production","titleAr":"تشييد أو إنتاج أو تحفيز أو تجديد الكولاجين / الإيلاستين / إنزيمات الجلد"},{"code":"CLAIM-الع-14","titleEn":"De-pigmentation","titleAr":"مُزيل أو يُخفّف التصبغات"},{"code":"CLAIM-الع-15","titleEn":"Prevents new spots / Eliminates age spots","titleAr":"يمنع البقع الجديدة من الظهور / يُنهي تبقع الجلد"},{"code":"CLAIM-الع-16","titleEn":"Any reference to hormones / phytohormones / phytoestrogens","titleAr":"أي إشارة إلى الهرمونات / الهرمونات النباتية / الإستروجينات النباتية"},{"code":"CLAIM-الع-17","titleEn":"Reduces the appearance of veins / capillaries","titleAr":"يُقلّل من مظهر الأوردة والشرايين"},{"code":"CLAIM-الع-18","titleEn":"Decongests Skin","titleAr":"يُقلّل من احتقان الجلد"},{"code":"CLAIM-الع-19","titleEn":"Decongesting","titleAr":"يُزيل احتقان الجلد"},{"code":"CLAIM-الع-2","titleEn":"Reduces / Slows aging","titleAr":"يُبطئ الشيخوخة / يُقلّل من التقدم في السن"},{"code":"CLAIM-الع-2-r84","titleEn":"Dandruff treatment","titleAr":"علاج القشرة"},{"code":"CLAIM-الع-2-r94","titleEn":"Removes / Whitens permanent stains (e.g., tetracycline-induced)","titleAr":"إزالة / تبييض البقع الدائمة (الناتجة من استخدام التيتراسيكلين)"},{"code":"CLAIM-الع-20","titleEn":"Any reference to rosacea","titleAr":"أي إشارة إلى مرض الوردية"},{"code":"CLAIM-الع-21","titleEn":"Therapeutic effect","titleAr":"تأثير علاجي"},{"code":"CLAIM-الع-22","titleEn":"Kills pathogens","titleAr":"يقتل مسببات الأمراض"},{"code":"CLAIM-الع-23","titleEn":"Kills germs","titleAr":"يقتل الجراثيم"},{"code":"CLAIM-الع-24","titleEn":"Kills bacteria / odour causing bacteria","titleAr":"يقتل البكتيريا المسببة للروائح"},{"code":"CLAIM-الع-25","titleEn":"Antiseptic","titleAr":"مطهر"},{"code":"CLAIM-الع-26","titleEn":"Disinfectant / Sanitizer","titleAr":"معقم / يقضي على البكتيريا"},{"code":"CLAIM-الع-27","titleEn":"Fungicide / Germicide / Virucide","titleAr":"مبيد الفطريات / الجراثيم / الفيروسات"},{"code":"CLAIM-الع-28","titleEn":"Cleans cuts (wounds)","titleAr":"يُنظّف الجروح"},{"code":"CLAIM-الع-29","titleEn":"Reference to disease-causing organisms","titleAr":"الإشارة إلى الميكروبات المسببة للأمراض"},{"code":"CLAIM-الع-3","titleEn":"Slows aging","titleAr":"يُبطئ التقدم في السن / يُؤخّر الشيخوخة"},{"code":"CLAIM-الع-3-r85","titleEn":"Eliminates dandruff permanently","titleAr":"ينهي القشرة نهائياً"},{"code":"CLAIM-الع-3-r95","titleEn":"Any references to the diseases of teeth or gum","titleAr":"أي إشارة إلى أمراض اللثة أو الأسنان"},{"code":"CLAIM-الع-30","titleEn":"Kills xx% of bacteria","titleAr":"يقتل XX% من البكتيريا"},{"code":"CLAIM-الع-31","titleEn":"Germ killing action","titleAr":"فعل قتل الجراثيم"},{"code":"CLAIM-الع-32","titleEn":"Stimulates circulation","titleAr":"يُحسّن الدورة الدموية"},{"code":"CLAIM-الع-33","titleEn":"Any impression or reference to disease prevention","titleAr":"أي تلميح أو إشارة إلى منع الأمراض"},{"code":"CLAIM-الع-34","titleEn":"Touch or reference to diseases","titleAr":"لمس أو إشارة إلى الأمراض"},{"code":"CLAIM-الع-35","titleEn":"Any reference to treatment / reduction of cellulite / orange peel skin","titleAr":"الإشارة إلى معالجة أو تقليل السيليولايت / تقشير الجلد"},{"code":"CLAIM-الع-36","titleEn":"Lose inches","titleAr":"خسارة إنشات من الجسم"},{"code":"CLAIM-الع-37","titleEn":"Removes fat","titleAr":"يُزيل الدهون"},{"code":"CLAIM-الع-38","titleEn":"Reshapes","titleAr":"إعادة تشكيل"},{"code":"CLAIM-الع-39","titleEn":"Restructures or slim the skin","titleAr":"إعادة تشكيل أو تنحيف أو الحد من الترهلات"},{"code":"CLAIM-الع-4","titleEn":"Prevents aging","titleAr":"يمنع التقدم في السن"},{"code":"CLAIM-الع-4-r86","titleEn":"Any reference to Alopecia","titleAr":"أي إشارة إلى الصلع"},{"code":"CLAIM-الع-4-r96","titleEn":"Relief gum and teeth pain","titleAr":"يخفف ألم الأسنان واللثة"},{"code":"CLAIM-الع-40","titleEn":"Slims / Slimming","titleAr":"تنحيف"},{"code":"CLAIM-الع-41","titleEn":"Cellulite (unqualified)","titleAr":"سيليولايت (بطرق غير مقبولة)"},{"code":"CLAIM-الع-42","titleEn":"Lipodraining / Melts fat","titleAr":"تصريف / إذابة الدهون"},{"code":"CLAIM-الع-43","titleEn":"Provides effect of medical / surgical procedure","titleAr":"يُعطي أثر التدخل الجراحي / الطبي"},{"code":"CLAIM-الع-44","titleEn":"Prevents acne","titleAr":"يمنع حب الشباب"},{"code":"CLAIM-الع-45","titleEn":"Heals acne","titleAr":"يشفي من حب الشباب"},{"code":"CLAIM-الع-46","titleEn":"Treats acne","titleAr":"يُعالج حب الشباب"},{"code":"CLAIM-الع-47","titleEn":"Stops acne","titleAr":"يوقف حب الشباب"},{"code":"CLAIM-الع-48","titleEn":"Any reference to effect on physiological growth of hair","titleAr":"أي إشارة للتأثير على النمو الفسيولوجي للشعر"},{"code":"CLAIM-الع-49","titleEn":"Stops hair from growing back","titleAr":"يمنع نمو الشعر من جديد"},{"code":"CLAIM-الع-5","titleEn":"Eliminates aging","titleAr":"يقضي على التقدم في السن"},{"code":"CLAIM-الع-5-r87","titleEn":"Treats / prevents / heals / stops hair loss","titleAr":"يعالج / يمنع / يشفي / يوقف تساقط الشعر"},{"code":"CLAIM-الع-6","titleEn":"Stops aging","titleAr":"يوقف التقدم في السن"},{"code":"CLAIM-الع-6-r88","titleEn":"Replace thinning hair","titleAr":"استبدال الشعر الرقيق"},{"code":"CLAIM-الع-7","titleEn":"Reverses aging","titleAr":"إعادة الشباب"},{"code":"CLAIM-الع-7-r89","titleEn":"Restore hair cells","titleAr":"استعادة خلايا الشعر"},{"code":"CLAIM-الع-8","titleEn":"Removes scars / sun damage","titleAr":"يُزيل الندبات والأضرار الناتجة عن الشمس"},{"code":"CLAIM-الع-8-r90","titleEn":"Stimulates hair growth","titleAr":"ينشط نمو الشعر"},{"code":"CLAIM-الع-9","titleEn":"Repairs sun damage","titleAr":"يُصلح الضرر الناتج عن الشمس"},{"code":"CLAIM-الع-9-r91","titleEn":"Root penetrating (i.e. any action under the scalp)","titleAr":"اختراق جذور الشعر (أي تأثير تحت فروة الرأس)"},{"code":"CLAIM-الن-1","titleEn":"Treats skin rash","titleAr":"يعالج الطفح الجلدي"},{"code":"CLAIM-الن-2","titleEn":"Replenishes / restores / replaces physiological or natural vaginal moisture","titleAr":"يغذي / يجدد / يستبدل الرطوبة الفسيولوجية للمهبل"},{"code":"CLAIM-الن-3","titleEn":"Enhances natural or physiological vaginal moisture","titleAr":"يُحسّن من الرطوبة الفسيولوجية للمهبل"},{"code":"CLAIM-الن-4","titleEn":"Replenishes / restores / replaces natural or physiological moisture from vaginal tissue","titleAr":"يغذي / يجدد / يستبدل الرطوبة الفسيولوجية لأنسجة المهبل"},{"code":"CLAIM-الن-5","titleEn":"Balanced pH to prevent infection","titleAr":"يحافظ على توازن درجة الحموضة لمنع العدوى"},{"code":"CLAIM-الن-6","titleEn":"Helps maintain normal pH level","titleAr":"يساعد على الحفاظ على المستوى الطبيعي لدرجة الحموضة"},{"code":"CLAIM-الن-